85|interface FlatStroke {
86|  d: string;
87|  stroke: string;
88|  width: number;
89|  opacity: number;
90|  fill?: string;
91|  blurred?: boolean;
92|}
93|
94|export function PictureDraw({ skin }: { skin: PictureSkin }) {
95|  const reduced = useReducedMotion();
96|  const uid = useId().replace(/[^a-zA-Z0-9]/g, "");
97|  const grainId = `pdg${uid}`;
98|  const softId = `pds${uid}`;
99|  const toolRef = useRef<SVGGElement | null>(null);
100|  const pathRefs = useRef<(SVGPathElement | null)[]>([]);
101|  // Four passes: outline then shading depth. Loops until unmounted.
102|  const layers = useMemo<FlatStroke[][]>(
103|    () => [0, 1, 2, 3].map((l) => strokesForSkin(skin, l)),
104|    [skin],
105|  );
106|  const stillAll = useMemo(() => stillStrokes(skin), [skin]);
107|  const still = reduced ? stillAll : null;
108|  const flat = useMemo(() => layers.flat(), [layers]);
109|
110|  useEffect(() => {
111|    if (reduced) return;
112|    const paths = pathRefs.current;
113|    const tool = toolRef.current;
114|    let dead = false;
115|    let frame = 0;
116|    const pos = { x: 340, y: 304 };
117|    const place = (x: number, y: number) => {
118|      pos.x = x;
119|      pos.y = y;
120|      tool?.setAttribute("transform", `translate(${x.toFixed(1)} ${y.toFixed(1)})`);
121|    };
122|    place(pos.x, pos.y);
123|
124|    const pointAt = (p: SVGPathElement, f: number): { x: number; y: number } | null => {
125|      try {
126|        if (typeof p.getPointAtLength !== "function" || typeof p.getTotalLength !== "function") return null;
127|        const pt = p.getPointAtLength(p.getTotalLength() * f);
128|        return { x: pt.x, y: pt.y };
129|      } catch {
130|        return null;
131|      }
132|    };
133|
134|    const runPass = () => {
135|      if (dead) return;
136|      // Restart the loop from the first pass shape.
137|      for (const p of paths) {
138|        if (!p) continue;
139|        p.style.strokeDashoffset = "1";
140|        p.setAttribute("opacity", "0");
141|      }
142|      let i = 0;
143|      const stepStroke = () => {
144|        if (dead) return;
145|        if (i >= paths.length) {
146|          frame = requestAnimationFrame(() => runPass());
147|          return;
148|        }
149|        const el = paths[i];
150|        const spec = flat[i];
151|        i += 1;
152|        if (!el || !spec) {
153|          stepStroke();
154|          return;
155|        }
156|        const dur = Math.min(1400, Math.max(150, spec.d.length * 3));
157|        const start = pointAt(el, 0);
158|        const t0 = performance.now();
159|        const TRAVEL = 100;
160|        const tick = (now: number) => {
161|          if (dead) return;
162|          if (now - t0 < TRAVEL) {
163|            if (start) {
164|              const k = (now - t0) / TRAVEL;
165|              place(pos.x + (start.x - pos.x) * k, pos.y + (start.y - pos.y) * k);
166|            }
167|            frame = requestAnimationFrame(tick);
168|            return;
169|          }
170|          const k = Math.min(1, (now - t0 - TRAVEL) / dur);
171|          if (spec.fill) {
172|            el.setAttribute("opacity", String(spec.opacity * k));
173|            if (k < 1) place(pos.x + Math.sin(k * 9) * 3, pos.y + Math.cos(k * 7) * 2);
174|          } else {
175|            el.setAttribute("opacity", String(spec.opacity));
176|            el.style.strokeDashoffset = String(1 - k);
177|            const pt = pointAt(el, k);
178|            if (pt) place(pt.x, pt.y);
179|          }
180|          if (k < 1) frame = requestAnimationFrame(tick);
181|          else stepStroke();
182|        };
183|        frame = requestAnimationFrame(tick);
184|      };
185|      stepStroke();
186|    };
187|    frame = requestAnimationFrame(() => runPass());
188|    return () => {
189|      dead = true;
190|      cancelAnimationFrame(frame);
191|    };
192|  }, [flat, reduced]);
193|
194|  return (
195|    <>
196|      <svg className="picdraw-art" viewBox="0 0 300 380" role="img" aria-label="Illustration being drawn">
197|        <defs>
198|          <filter id={grainId} x="0" y="0" width="1" height="1">
199|            <feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves="2" seed="3" />
200|            <feColorMatrix values="0 0 0 0 .32 0 0 0 0 .25 0 0 0 0 .14 0 0 0 .10 0" />
201|          </filter>
202|          <filter id={softId} x="-50%" y="-50%" width="200%" height="200%">
203|            <feGaussianBlur stdDeviation="1.2" />
204|          </filter>
205|        </defs>
206|        <Paper skin={skin} grainId={grainId} />
207|        <g>
208|          {(still ?? flat).map((s, i) => (
209|            <path
210|              key={i}
211|              ref={still ? undefined : (el) => {
212|                pathRefs.current[i] = el;
213|              }}
214|              d={s.d}
215|              fill={s.fill ?? "none"}
216|              stroke={s.stroke}
217|              strokeWidth={s.width || undefined}
218|              opacity={still ? s.opacity : 0}
219|              pathLength={s.fill ? undefined : 1}
220|              style={s.fill || still ? undefined : { strokeDasharray: "1", strokeDashoffset: "1" }}
221|              filter={s.blurred ? `url(#${softId})` : undefined}
222|              strokeLinecap="round"
223|              strokeLinejoin="round"
224|            />
225|          ))}
226|        </g>
227|        <g ref={toolRef} className="picdraw-tool" transform="translate(254 340)">
228|          <Tool skin={skin} />
229|        </g>
230|      </svg>
231|      <div className="picdraw-status">
232|        <span className="picdraw-t">{DRAW_STATUS[skin]}</span>
233|        <span className="picdraw-n">{DRAW_NOTE}</span>
234|      </div>
235|    </>
236|  );
237|}

