1|// Inline figures: the selection popover plus the figures rendered
2|// after their end paragraph. Click opens the lightbox.
3|"use client";
4|
5|import { truncateCaption } from "./helpers";
6|import { PICTURE_COPY, PictureIcon } from "./picture-copy";
7|import { PictureDraw } from "./picture-draw";
8|import { usePictureSkin } from "./picture-skin";
9|import type { InlineFigure } from "./use-pictures";
10|
11|export function SelectionPopover({
12|  pos,
13|  popRef,
14|  onPick,
15|}: {
16|  pos: { top: number; left: number };
17|  popRef: React.Ref<HTMLButtonElement>;
18|  onPick: () => void;
19|}) {
20|  return (
21|    <button
22|      type="button"
23|      ref={popRef}
24|      className="picture-float"
25|      style={{ top: pos.top, left: pos.left }}
26|      onClick={onPick}
27|      aria-label="Picture this"
28|    >
29|      <PictureIcon size={12} />
30|      Picture this
31|    </button>
32|  );
33|}
34|
35|export function InlineFigureView({
36|  figure,
37|  onRemove,
38|  onRetry,
39|  onOpen,
40|  refCb,
41|}: {
42|  figure: InlineFigure;
43|  onRemove: () => void;
44|  onRetry: () => void;
45|  onOpen: (src: string, caption: string, opener: HTMLElement | null) => void;
46|  refCb: (el: HTMLElement | null) => void;
47|}) {
48|  const skin = usePictureSkin();
49|  if (figure.phase === "loading") {
50|    return (
51|      <figure className="genfig" data-fig={figure.id} ref={refCb as React.Ref<HTMLElement>}>
52|        <div className="genload" role="status">
53|          <PictureDraw skin={skin} />
54|        </div>
55|      </figure>
56|    );
57|  }
58|  if (figure.phase === "error") {
59|    return (
60|      <figure className="genfig" data-fig={figure.id} ref={refCb as React.Ref<HTMLElement>}>
61|        <p className="gen-error" role="alert">
62|          {figure.message}{" "}
63|          <button type="button" className="retry-text" onClick={onRetry}>
64|            {PICTURE_COPY.retry}
65|          </button>
66|        </p>
67|      </figure>
68|    );
69|  }
70|  if (!figure.url) return null;
71|  const url = figure.url;
72|  const captioned = `\u201C${truncateCaption(figure.quote)}\u201D`;
73|  return (
74|    <figure className="genfig" data-fig={figure.id} ref={refCb as React.Ref<HTMLElement>}>
75|      <img
76|        className={`rv-${skin}`}
77|        src={url}
78|        alt={captioned}
79|        tabIndex={0}
80|        onClick={(e) => onOpen(url, captioned, e.currentTarget)}
81|        onKeyDown={(e) => {
82|          if (e.key === "Enter") onOpen(url, captioned, e.currentTarget);
83|        }}
84|      />
85|      <figcaption>
86|        <span className="grow">{captioned}</span>
87|        <span className="gcredit">{figure.credit}</span>
88|        <button
