7|import { PictureButton } from "./picture-button";
8|import { PictureDraw } from "./picture-draw";
9|import { usePictureSkin } from "./picture-skin";
10|import type { SceneCard } from "./use-pictures";
11|
12|export function ImagePane({
13|  card,
14|  onPicture,
15|  onRetry,
16|  onClear,
17|  onOpen,
18|  bare,
19|  onPictureChapter,
20|}: {
21|  card: SceneCard;
22|  onPicture: () => void;
23|  onRetry: () => void;
24|  onClear: () => void;
25|  onOpen: (src: string, caption: string, opener: HTMLElement | null) => void;
26|  // The cover shows the placeholder with no pill: nothing to picture yet.
27|  bare?: boolean;
28|  // On text pages the pill pairs the scene action with the chapter one.
29|  onPictureChapter?: ((opener: HTMLElement | null) => void) | null;
30|}) {
31|  const [expanded, setExpanded] = useState(false);
32|  const timer = useRef<number | null>(null);
33|  const skin = usePictureSkin();
34|
35|  function armExpand() {
36|    if (timer.current !== null) return;
37|    timer.current = window.setTimeout(() => {
38|      timer.current = null;
39|      setExpanded(true);
40|    }, 250);
41|  }
42|
43|  function cancelExpand() {
44|    if (timer.current !== null) {
45|      window.clearTimeout(timer.current);
46|      timer.current = null;
47|    }
48|    setExpanded(false);
49|  }
50|
51|  return (
52|    <section className="img-pane" aria-label="Illustration">
53|      <div className="frame">
54|        {card.phase === "idle" ? (
55|          <>
56|            <div className="paper-grain" aria-hidden="true">
57|              <span className="blob b1" />
58|              <span className="blob b2" />
59|              <span className="blob b3" />
60|              <span className="grain" />
61|            </div>
62|            {bare ? null : onPictureChapter ? (
63|              <span className="pic-pair" role="group" aria-label="Picture choices">
64|                <PictureButton skin={skin} label="Picture this scene" onClick={onPicture} />
65|                <PictureButton
66|                  skin={skin}
67|                  label="Picture the chapter"
68|                  onClick={(e) => onPictureChapter(e.currentTarget)}
69|                />
70|              </span>
71|            ) : (
72|              <PictureButton skin={skin} label="Picture this scene" onClick={onPicture} />
73|            )}
74|          </>
75|        ) : card.phase === "loading" ? (
76|          <div className="pane-loading" role="status">
77|            <PictureDraw skin={skin} />
78|          </div>
79|        ) : card.phase === "ready" ? (
80|          <>
81|            <img
82|              className={`pane-img rv-${skin}`}
83|              src={card.url}
84|              alt={card.caption}
85|              tabIndex={0}
86|              onMouseEnter={armExpand}
87|              onMouseLeave={cancelExpand}
88|              onFocus={cancelExpand}
89|              onClick={(e) => {
90|                cancelExpand();
91|                onOpen(card.url, card.caption, e.currentTarget);
92|              }}
93|              onKeyDown={(e) => {
94|                if (e.key === "Enter") onOpen(card.url, card.caption, e.currentTarget);
95|              }}
96|            />
97|            {expanded ? (
98|              <>
99|                <div className="expand-dim" aria-hidden="true" />
100|                <img
101|                  className="expand-img"
102|                  src={card.url}
103|                  alt=""
104|                  onMouseLeave={cancelExpand}
105|                  onClick={() => {
106|                    cancelExpand();
107|                    onOpen(card.url, card.caption, null);
108|                  }}
109|                />
110|              </>
111|            ) : null}
112|          </>
113|        ) : (
114|          <div className="pane-error" role="alert">
115|            <p>{card.message}</p>
116|            <button type="button" className="retry-text" onClick={onRetry}>
117|              {PICTURE_COPY.retry}
118|            </button>
119|          </div>
120|        )}
121|      </div>
122|      {card.phase === "ready" ? (
123|        <div className="pane-cap">
124|          <span className="pane-cap-text">{card.caption}</span>
125|          <button
126|            type="button"
127|            className="pane-x"
128|            onClick={onClear}
129|            aria-label={PICTURE_COPY.remove}
130|            title={PICTURE_COPY.remove}
131|          >
132|            ×
133|          </button>
134|        </div>
135|      ) : null}
136|      {card.phase === "ready" && onPictureChapter ? (
137|        <button type="button" className="pane-chapter" onClick={(e) => onPictureChapter(e.currentTarget)}>
138|          Picture the chapter
139|        </button>
140|      ) : null}
141|    </section>
142|  );
