49|  wind2: "M62 120q24-9 48 0",
50|  dorothy: "M60 236a7 7 0 1 0 .1 0M60 250L48 282H72ZM50 260L40 252M70 260L80 250M55 282v8M65 282v8",
51|  toto: "M86 284c-2-8 4-12 10-10c4-6 10-2 8 3c2 4-2 8-6 7c-4 3-10 3-12 0zM90 285v4M100 285v4",
52|};
53|
54|const CONTOURS: (keyof typeof C)[] = [
55|  "ground", "wall", "roof", "door", "window", "chimney",
56|  "dorothy", "toto", "funnel", "cloud", "wind1", "wind2",
57|];
58|
59|const OVAL = "M150 26C230 26 282 100 282 190S230 354 150 354S18 280 18 190S70 26 150 26Z";
60|const OVAL_INNER = "M150 34C224 34 274 104 274 190S224 346 150 346S26 276 26 190S76 34 150 34Z";
61|
62|function ovalPts(): Pt[] {
63|  return Array.from({ length: 28 }, (_, i) => [
64|    150 + 128 * Math.cos((i / 28) * 2 * Math.PI),
65|    190 + 160 * Math.sin((i / 28) * 2 * Math.PI),
66|  ]) as Pt[];
67|}
68|
69|function clip(poly: Pt[], p0: Pt, d: Pt): Pt[] | null {
70|  const c: Pt = poly.reduce<Pt>((a, p) => [a[0] + p[0] / poly.length, a[1] + p[1] / poly.length], [0, 0]);
71|  let t0 = -1e4;
72|  let t1 = 1e4;
73|  for (let i = 0; i < poly.length; i++) {
74|    const a = poly[i];
75|    const b = poly[(i + 1) % poly.length];
76|    if (!a || !b) return null;
77|    let n: Pt = [-(b[1] - a[1]), b[0] - a[0]];
78|    if (n[0] * (c[0] - a[0]) + n[1] * (c[1] - a[1]) < 0) n = [-n[0], -n[1]];
79|    const den = n[0] * d[0] + n[1] * d[1];
80|    const num = n[0] * (p0[0] - a[0]) + n[1] * (p0[1] - a[1]);
81|    if (Math.abs(den) < 1e-9) {
82|      if (num < 0) return null;
83|    } else {
84|      const t = -num / den;
85|      if (den > 0) t0 = Math.max(t0, t);
86|      else t1 = Math.min(t1, t);
87|    }
88|  }
89|  return t0 < t1
90|    ? [[p0[0] + d[0] * t0, p0[1] + d[1] * t0], [p0[0] + d[0] * t1, p0[1] + d[1] * t1]]
91|    : null;
92|}
93|
94|function hatch(poly: Pt[], deg: number, gap: number, jit: number, r: Rng): Pt[][] {
95|  const a = (deg * Math.PI) / 180;
96|  const d: Pt = [Math.cos(a), Math.sin(a)];
97|  const n: Pt = [-d[1], d[0]];
98|  const pr = poly.map((p) => p[0] * n[0] + p[1] * n[1]);
99|  const lo = Math.min(...pr);
100|  const hi = Math.max(...pr);
101|  const out: Pt[][] = [];
102|  for (let s = lo + gap / 2; s < hi; s += gap) {
103|    const seg = clip(poly, [n[0] * (s + (r() - 0.5) * jit), n[1] * (s + (r() - 0.5) * jit)], d);
104|    const s0 = seg?.[0];
105|    const s1 = seg?.[1];
106|    if (s0 && s1 && Math.hypot(s1[0] - s0[0], s1[1] - s0[1]) > 4) out.push(seg);
107|  }
108|  return out;
109|}
110|
111|function segD(seg: Pt[], inset = 2): string {
112|  const a = seg[0];
113|  const b = seg[1];
114|  if (!a || !b) return "";
115|  const L = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1;
116|  const ux = (b[0] - a[0]) / L;
117|  const uy = (b[1] - a[1]) / L;
118|  return `M${(a[0] + ux * inset).toFixed(1)} ${(a[1] + uy * inset).toFixed(1)}L${(b[0] - ux * inset).toFixed(1)} ${(b[1] - uy * inset).toFixed(1)}`;
119|}
120|
121|function zigzag(segs: Pt[][]): string {
122|  let out = "";
123|  segs.forEach((s, i) => {
124|    const a = s[i % 2 ? 1 : 0];
125|    const b = s[i % 2 ? 0 : 1];
126|    if (!a || !b) return;
127|    out += `${i ? "L" : "M"}${a[0].toFixed(1)} ${a[1].toFixed(1)}L${b[0].toFixed(1)} ${b[1].toFixed(1)}`;
128|  });
129|  return out;
130|}
131|
132|function blobPath(x: number, y: number, rad: number, r: Rng): string {
133|  const k = 9;
134|  const pts: Pt[] = Array.from({ length: k }, (_, i) => {
135|    const a = (i / k) * 2 * Math.PI;
136|    const rr = rad * (0.75 + r() * 0.45);
137|    return [x + Math.cos(a) * rr, y + Math.sin(a) * rr * 0.82];
138|  });
139|  const first: Pt = pts[0] ?? [x, y];
140|  const last: Pt = pts[k - 1] ?? [x, y];
141|  let d = `M${((first[0] + last[0]) / 2).toFixed(1)} ${((first[1] + last[1]) / 2).toFixed(1)}`;
142|  for (let i = 0; i < k; i++) {
143|    const p: Pt = pts[i] ?? [x, y];
144|    const q: Pt = pts[(i + 1) % k] ?? [x, y];
145|    d += `Q${p[0].toFixed(1)} ${p[1].toFixed(1)} ${((p[0] + q[0]) / 2).toFixed(1)} ${((p[1] + q[1]) / 2).toFixed(1)}`;
146|  }
147|  return d + "Z";
148|}
149|
150|const INK = "#2A241C";
151|const BLUE = "#0866FF";
152|
153|function engravingLayer(layer: number): DrawStroke[] {
154|  const r = rng(3 + layer);
155|  if (layer === 0) {
156|    const out: DrawStroke[] = [
157|      { d: OVAL, stroke: INK, width: 1.1, opacity: 1 },
158|      { d: OVAL_INNER, stroke: INK, width: 0.5, opacity: 1 },
159|    ];
160|    for (const k of CONTOURS) {
161|      out.push({ d: C[k], stroke: INK, width: k === "funnel" ? 1.2 : 0.9, opacity: 1 });
162|    }
163|    return out;
164|  }
165|  const oval = ovalPts();
166|  const polys: [Pt[], number, number][] = [
167|    [R.sky, layer % 2 ? -40 : 40, 6 + layer],
168|    [R.ground, layer % 2 ? 20 : -20, 5 + layer],
169|    [R.roof, layer % 2 ? 60 : -60, 4 + layer],
170|  ];
171|  const out: DrawStroke[] = [];
172|  for (const [poly, deg, gap] of polys) {
173|    for (const s of hatch(poly, deg, gap, 1, r)) {
174|      const a = s[0];
175|      const b = s[1];
176|      if (!a || !b) continue;
177|      const len = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1;
178|      const inside = clip(oval, a, [(b[0] - a[0]) / len, (b[1] - a[1]) / len]);
179|      if (inside) out.push({ d: segD(inside, 3), stroke: INK, width: 0.45, opacity: 0.7 });
180|    }
181|  }
182|  return out;
183|}
184|
185|const SPOTS: [number, number, string, number][] = [
186|  [70, 70, "#9FC4FF", 46], [160, 56, "#C9DDF7", 52], [232, 96, "#7FB0FF", 40],
187|  [262, 180, "#9AA3B5", 30], [256, 250, "#9AA3B5", 24], [150, 190, "#C9785A", 36],
188|  [150, 246, "#E6C27A", 44], [110, 250, "#E6C27A", 30], [60, 262, "#6FA0E8", 18],
189|  [90, 318, "#B9C98A", 48], [200, 322, "#B9C98A", 52], [150, 350, "#CFD9A8", 40],
190|];
191|
192|function watercolorLayer(layer: number): DrawStroke[] {
193|  const r = rng(11 + layer);
194|  const spots = layer ? [...SPOTS].sort(() => r() - 0.5) : SPOTS;
195|  return spots.map(([x, y, c, rad]) => {
196|    const jx = x + (r() - 0.5) * 24 * layer;
197|    const jy = y + (r() - 0.5) * 18 * layer;
198|    return {
199|      d: blobPath(jx, jy, rad * (layer ? 0.7 : 1), r),
200|      stroke: "none",
201|      width: 0,
202|      opacity: layer ? 0.35 : 0.6,
203|      fill: c,
204|      blurred: true,
205|    };
206|  });
207|}
208|
209|const INK_REGIONS: [Pt[], number, number][] = [
210|  [R.roof, -35, 6], [R.ground, 8, 9], [R.wall, 70, 10], [R.sky, -12, 16],
211|];
212|
213|function inkLayer(layer: number): DrawStroke[] {
214|  if (layer === 0) {
215|    return CONTOURS.map((k) => ({
216|      d: C[k],
217|      stroke: BLUE,
218|      width: k === "funnel" ? 2.2 : 1.8,
219|      opacity: 1,
220|    }));
221|  }
222|  const r = rng(9 + layer);
223|  const fallback: [Pt[], number, number] = [R.ground, 8, 9];
224|  const [poly, deg, gap] = INK_REGIONS[(layer - 1) % INK_REGIONS.length] ?? fallback;
225|  return [{
226|    d: zigzag(hatch(poly, deg, gap, 2, r)),
227|    stroke: BLUE,
228|    width: 1.1,
229|    opacity: 0.55,
230|  }];
231|}
232|
233|// Layer 0 is the outline pass; higher layers cycle shading/wash depth.
234|export function strokesForSkin(skin: PictureSkin, layer: number): DrawStroke[] {
235|  if (skin === "watercolor") return watercolorLayer(layer);
236|  if (skin === "ink") return inkLayer(layer);
237|  return engravingLayer(layer);
238|}
239|
240|const STILL_SPOTS: [number, number, string, number][] = [
241|  [70, 70, "#9FC4FF", 46], [160, 56, "#C9DDF7", 52],
242|  [150, 246, "#E6C27A", 44], [150, 190, "#C9785A", 36],
243|  [200, 322, "#B9C98A", 52],
244|];
245|
246|export function stillStrokes(skin: PictureSkin): DrawStroke[] {
247|  if (skin === "watercolor") {
248|    const r = rng(2);
249|    return STILL_SPOTS.map(([x, y, c, rad]) => ({
250|      d: blobPath(x, y, rad, r),
251|      stroke: "none",
252|      width: 0,
253|      opacity: 0.6,
254|      fill: c,
255|      blurred: true,
256|    }));
257|  }
258|  const out: DrawStroke[] = [];
259|  if (skin === "engraving") {
260|    out.push({ d: OVAL, stroke: INK, width: 1.1, opacity: 1 });
261|  }
262|  const color = skin === "engraving" ? INK : BLUE;
263|  for (const k of CONTOURS) out.push({ d: C[k], stroke: color, width: 1.4, opacity: 0.9 });
264|  return out;
265|}
266|
267|export const DRAW_STATUS: Record<PictureSkin, string> = {
268|  engraving: "Etching the plate…",
269|  watercolor: "Letting the colours bloom…",
270|  ink: "Doodling your scene…",
271|};
272|
273|export const DRAW_NOTE = "Usually about twenty seconds";

