9|
10|(globalThis as { IS_REACT_ACT_ENVIRONMENT?: boolean }).IS_REACT_ACT_ENVIRONMENT = true;
11|
12|function Harness({ card }: { card: SceneCard }) {
13|  return (
14|    <ImagePane
15|      card={card}
16|      onPicture={() => {}}
17|      onRetry={() => {}}
18|      onClear={() => {}}
19|      onOpen={() => {}}
20|    />
21|  );
22|}
23|
24|afterEach(() => {
25|  document.body.innerHTML = "";
26|  vi.unstubAllGlobals();
27|});
28|
29|test("loading shows the drawing and status, ready shows the image", () => {
30|  // No drawing progress: frames never fire, so nothing can block the flip.
31|  vi.stubGlobal("requestAnimationFrame", () => 0);
